import{_ as e,c as i,o as a,aj as o}from"./chunks/framework.CMWtagCP.js";const m=JSON.parse('{"title":"biology","description":"","frontmatter":{"title":"biology","hugoSource":"science/biology.md","outline":[1,6]},"headers":[],"relativePath":"knowledge/science/2026-11-17-biology.md","filePath":"knowledge/science/2026-11-17-biology.md","lastUpdated":1794887319000}'),t={name:"knowledge/science/2026-11-17-biology.md"};function n(r,l,c,s,d,u){return a(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="线粒体" tabindex="-1">线粒体 <a class="header-anchor" href="#线粒体" aria-label="Permalink to “线粒体”">​</a></h1><ul><li>线粒体的任务很简单：把我们吃下去的糖和脂肪，转化为细胞可以使用的能量分子，ATP。没有它，人的心跳会停、呼吸会断，连神经之间的信息传导都无法完成。它是生命体内最基础，却最不可或缺的“动力单元”。</li><li>不同于细胞中大多数基因都储存在细胞核里，线粒体有一套独立的小型基因组，叫线粒体DNA（mtDNA）。更特别的是，这套遗传信息几乎完全来自母亲。</li></ul><h2 id="线粒体病" tabindex="-1">线粒体病 <a class="header-anchor" href="#线粒体病" aria-label="Permalink to “线粒体病”">​</a></h2><ul><li>PGT（胚胎植入前遗传学检测） <ul><li>通过筛选胚胎中mtDNA突变比例较低者进行移植，相当于在一组不确定选项中，谨慎地挑出那个最可能避开疾病的“好签”；</li><li>该方法前提 <ul><li>女性体内必须存在多个突变水平较低的胚胎可供选择。对于mtDNA突变比例极高的女性来说，PGT往往无解，她们体内根本没有“可选项”。</li></ul></li></ul></li><li>PNT（原核移植） <ul><li>则是在受精刚完成的原核阶段，将父母的细胞核移植进一枚去核的健康捐赠卵子中，从源头更换线粒体，完成一次细胞层级的“偷天换日”。</li><li>科学家将受精卵中的细胞核DNA转移到一枚健康女性捐赠的、已去核的卵子中，保留父母遗传信息，更换线粒体“供能系统”。这就产生了所谓的“三亲婴儿”，孩子的细胞核来自父母，而线粒体DNA来自第三方女性捐赠者。</li><li>争议 <ul><li>伦理争议的焦点并不仅仅在于“这是不是改造”，更在于“它会不会成为一个滑坡起点”。一旦社会接受了“为了避免疾病可以更换DNA”，是否也会接受“为了提高素质可以优化DNA”？当修改线粒体成为合法选项，是否也会让“定制婴儿”的概念顺势潜入现实？尤其是在资源分配不平等的世界中，技术本身中立，使用它的人却未必如此。 <ul><li>现实中，各国对这项技术的态度明显分化。英国在2015年成为全球首个立法批准线粒体捐赠治疗的国家，并设置了严格的个案审批机制。澳大利亚、乌克兰等国也在特定框架内尝试推进。而美国则态度保守，至今不允许在临床中使用会遗传改变的胚胎技术，相关研究只能停留在实验室层面。</li></ul></li></ul></li></ul></li></ul>',4)])])}const h=e(t,[["render",n]]);export{m as __pageData,h as default};
